package proxy

import (
	"bytes"
	_ "embed"
	"fmt"
	"html/template"
	"net/http"
	"strings"
)

//go:embed error.html
var errorPageHTML string

var errorPageTemplate = template.Must(template.New("error").Parse(errorPageHTML))

type errorPage struct {
	Code                     int
	Title, Message, NextStep string
}

// Codes for HTTP errors generated by HAProxy itself.
var errorPages = []errorPage{
	{400, "Invalid request", "The request could not be understood.", "Check the address and try again."},
	{403, "Access denied", "This request is blocked by the site's access rules.", "Contact the site operator if you need access."},
	{404, "Site not found", "There is no site configured for this address.", "Check the address or follow a link from the site operator."},
	{405, "Method not allowed", "This address does not accept that type of request.", "Try opening the address directly in your browser."},
	{408, "Request timed out", "The request took too long to arrive.", "Check your connection and try again."},
	{410, "Page removed", "This address is no longer available.", "Check with the site operator for a new address."},
	{413, "Request too large", "The request exceeds the site's size limit.", "Send a smaller file or reduce the amount of data."},
	{414, "Address too long", "The requested address exceeds the site's length limit.", "Try opening a shorter address."},
	{425, "Request sent too early", "The secure connection was still being established.", "Try again once the connection is ready."},
	{429, "Too many requests", "The site has reached its request limit.", "Wait a moment before trying again."},
	{431, "Request headers too large", "The request included too much header data.", "Try again in a private browser window."},
	{500, "Unexpected error", "The gateway could not complete your request.", "Try again in a moment."},
	{501, "Request not supported", "The gateway cannot handle this type of request.", "Contact the site operator if the problem continues."},
	{502, "Bad gateway", "The application sent a response the gateway could not use.", "Try again in a moment."},
	{503, "Service unavailable", "The application cannot serve requests right now.", "Try again in a moment."},
	{504, "Gateway timeout", "The application did not respond in time.", "Try again in a moment."},
}

func renderErrorConfig(config *strings.Builder) {
	config.WriteString("http-errors shipyard\n")
	for _, page := range errorPages {
		fmt.Fprintf(config, "  errorfile %d /usr/local/etc/haproxy/errors/%d.http\n", page.Code, page.Code)
	}
	config.WriteByte('\n')
}

func renderErrorResponse(page errorPage) ([]byte, error) {
	var body bytes.Buffer
	if err := errorPageTemplate.Execute(&body, page); err != nil {
		return nil, err
	}
	headers := fmt.Sprintf("HTTP/1.1 %d %s\r\nContent-Type: text/html; charset=utf-8\r\nCache-Control: no-store\r\nContent-Length: %d\r\n\r\n", page.Code, http.StatusText(page.Code), body.Len())
	return append([]byte(headers), body.Bytes()...), nil
}
